{
  "name": "CVD 薄膜沉积系统",
  "name_en": "CVD Thin-Film Deposition System",
  "manufacturer": "",
  "description": "用于化学气相沉积工艺的实验室设备，通过控制多路工艺气体流量与温度设定点，按预设配方在基底上沉积薄膜。设备通常包含反应腔体、加热单元、气体进气与质量流量控制模块，并支持配方管理与过程监控，以实现稳定可重复的薄膜生长。",
  "description_en": "A laboratory Chemical Vapor Deposition system that deposits thin films by controlling multiple process gas flows and a temperature setpoint according to a predefined recipe. The system typically includes a reaction chamber, heater, gas inlets with mass flow control, and supports recipe management and process monitoring for stable and repeatable film growth.",
  "actions": [
    {
      "action_name": "auto-return_ui_fields",
      "description": "获取当前界面中的工艺参数字段（如气体列名、流量与温度设定等），用于查看或记录配置。",
      "description_en": "Retrieve the current process parameter fields from the interface (e.g., gas labels, flow values, temperature setpoint) for review or logging."
    },
    {
      "action_name": "auto-save_recipe",
      "description": "将当前工艺配方保存到文件（包含元数据、气体列与步骤参数），以便复用与追踪。",
      "description_en": "Save the current process recipe to a file, including metadata, gas columns, and step parameters for reuse and traceability."
    },
    {
      "action_name": "auto-open_recipe",
      "description": "从文件加载工艺配方并填充界面参数与气体标签，用于准备运行。",
      "description_en": "Load a process recipe from a file and populate the interface parameters and gas labels in preparation for execution."
    },
    {
      "action_name": "auto-update_plot",
      "description": "刷新并更新气体流量与时间的趋势曲线，用于过程可视化。",
      "description_en": "Refresh and update the time-series plots of gas flows for process visualization."
    },
    {
      "action_name": "auto-start_recipe",
      "description": "启动已加载的工艺配方运行，进入运行状态并更新曲线显示。",
      "description_en": "Start executing the loaded process recipe, switch to RUNNING state, and update the plots."
    },
    {
      "action_name": "auto-stop_recipe",
      "description": "停止当前工艺配方的运行并退出运行状态。",
      "description_en": "Stop the currently running process recipe and exit the running state."
    },
    {
      "action_name": "auto-apply_setpoints",
      "description": "应用并显示当前设定的温度等设定点参数。",
      "description_en": "Apply and display the current setpoint parameters such as temperature."
    }
    ],
  "tag_hints": [
    "CVD",
    "thin film deposition",
    "gas flow control",
    "process recipe management",
    "temperature setpoint",
    "semiconductor processing",
    "process monitoring"
  ]
}
